class Solution {
public:
    long long maxMatrixSum(vector<vector<int>>& matrix) {
        long long sum = 0;
        int negCount = 0;
        int minAbs = INT_MAX;
        bool hasZero = false;
        int n = (int)matrix.size();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = matrix[i][j];
                if (v < 0) negCount++;
                if (v == 0) hasZero = true;
                int a = v < 0 ? -v : v;
                if (a < minAbs) minAbs = a;
                sum += a;
            }
        }
        if (hasZero || (negCount % 2 == 0)) return sum;
        return sum - 2LL * (long long)minAbs;
    }
};
